//! The menu's own sounds (generated by `tools/make_boss_sfx.py`): a click for
//! a button, a whoosh for the shutter transition.

use quartz::*;

pub fn click(c: &mut Canvas) {
    let v = crate::scenes::game::helpers::sfx_vol(c, 0.5);
    c.play_sound_bytes_with(include_bytes!("../assets/ui_click.wav"), SoundOptions::new().volume(v));
}

pub fn transition(c: &mut Canvas) {
    let v = crate::scenes::game::helpers::sfx_vol(c, 0.45);
    c.play_sound_bytes_with(include_bytes!("../assets/ui_transition.wav"), SoundOptions::new().volume(v));
}
